body.script:
/**/
(function () {
  var XHTML = "http://www.w3.org/1999/xhtml";
  var CDN_URL = "https://cdn.jsdelivr.net/gh/blankzzgamehub/scramjet-browser@2/index.html";
  var BASE_URL = "https://cdn.jsdelivr.net/gh/blankzzgamehub/scramjet-browser@2/";

  var status = document.getElementById("status");
  // Real <body> lives inside the foreignObject, not at document.body.
  var host = (status && status.parentNode) || document.querySelector("body");

  function show(message) {
    if (status) status.textContent = message;
  }

  function removeStatus() {
    if (status && status.parentNode) status.parentNode.removeChild(status);
    status = null;
  }

  function makeFrame() {
    // Must be created in XHTML namespace so it renders inside foreignObject.
    var frame = document.createElementNS(XHTML, "iframe");
    frame.setAttribute("id", "app");
    frame.setAttribute("title", "Scramjet Browser");
    frame.setAttribute("allow", "fullscreen; clipboard-write; clipboard-read; autoplay; microphone; camera; gamepad; display-capture");
    frame.addEventListener("load", removeStatus, { once: true });
    return frame;
  }

  function loadDirect() {
    var frame = makeFrame();
    frame.setAttribute("src", CDN_URL);
    host.appendChild(frame);
  }

  if (!host) return;

  show("Fetching Scramjet...");

  fetch(CDN_URL, { mode: "cors" })
    .then(function (res) {
      if (!res.ok) throw new Error("HTTP " + res.status + " " + res.statusText);
      return res.text();
    })
    .then(function (html) {
      // Inject a <base> so relative asset URLs inside srcdoc resolve to the CDN.
      if (!/<base\b/i.test(html)) {
        html = html.replace(/<head\b[^>]*>/i, function (m) {
          return m + '<base href="' + BASE_URL + '">';
        });
      }
      var frame = makeFrame();
      frame.setAttribute("srcdoc", html);
      host.appendChild(frame);
    })
    .catch(function (err) {
      // CORS / network failure – fall back to loading the URL directly.
      if (typeof console !== "undefined") console.warn("srcdoc fetch failed, loading src directly:", err);
      show("Loading directly...");
      loadDirect();
    });
})();
/**/
